"""Strict dates, month arithmetic and periods."""
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

from .errors import ParseError


class DateError(ParseError):
    pass


def is_date(x):
    return isinstance(x, date) and not isinstance(x, datetime)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': expected text" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= month <= 12 or not 1 <= year <= 9999:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    if not _is_int(n):
        raise DateError("months must be an integer, got '%s'" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    y, m = divmod(total, 12)
    m += 1
    if not 1 <= y <= 9999:
        raise DateError("date out of range: %s plus %d months" % (format_date(d), n))
    return date(y, m, min(d.day, last_day(y, m)))


@dataclass(frozen=True)
class Period:
    start: date
    end: date

    def __post_init__(self):
        if not is_date(self.start) or not is_date(self.end):
            raise DateError("period needs two dates, got '%s' and '%s'" % (self.start, self.end))
        if self.end < self.start:
            raise DateError("empty period: %s is before %s" % (format_date(self.end), format_date(self.start)))

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: '%s'" % (d,))
        return self.start <= d <= self.end

    @property
    def days(self):
        return (self.end - self.start).days + 1

    def _kind(self):
        s, e = self.start, self.end
        if s.day != 1:
            return None
        if s.month == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if e.year == s.year and e.month == s.month and e.day == last_day(e.year, e.month):
            return "month"
        if (
            s.month in (1, 4, 7, 10)
            and e.year == s.year
            and e.month == s.month + 2
            and e.day == last_day(e.year, e.month)
        ):
            return "quarter"
        return None

    @property
    def label(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self.start), format_date(self.end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        s = self.start
        try:
            if kind == "year":
                return _year(s.year + 1)
            if kind == "month":
                return _month_after(s)
            if kind == "quarter":
                nxt = add_months(s, 3)
                return _span(nxt, add_months(nxt, 3) - timedelta(days=1))
            ns = self.end + timedelta(days=1)
            return Period(ns, ns + timedelta(days=self.days - 1))
        except OverflowError:
            raise DateError("period after %s is out of range" % self.label) from None

    @staticmethod
    def parse(text):
        return _parse_period(text)


def _span(a, b):
    return Period(a, b)


def _year(y):
    if not 1 <= y <= 9999:
        raise DateError("year %d is out of range" % y)
    return Period(date(y, 1, 1), date(y, 12, 31))


def _month_after(s):
    nxt = add_months(s, 1)
    return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))


def _month_of(y, m):
    return Period(date(y, m, 1), date(y, m, last_day(y, m)))


_YEAR_RE = re.compile(r"([0-9]{4})")
_MONTH_RE = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER_RE = re.compile(r"([0-9]{4})-Q([1-4])")


def _parse_period(text):
    if not isinstance(text, str):
        raise DateError("invalid period '%s': expected text" % (text,))
    try:
        m = _YEAR_RE.fullmatch(text)
        if m:
            return _year(int(m.group(1)))
        m = _MONTH_RE.fullmatch(text)
        if m:
            return _month_of(int(m.group(1)), int(m.group(2)))
        m = _QUARTER_RE.fullmatch(text)
        if m:
            y, q = int(m.group(1)), int(m.group(2))
            first = _month_of(y, 3 * q - 2)
            return Period(first.start, _month_of(y, 3 * q).end)
        parts = text.split("..")
        if len(parts) == 2:
            return Period(parse_date(parts[0]), parse_date(parts[1]))
    except (DateError, ValueError):
        pass
    raise DateError("invalid period '%s'" % text)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        start = d - timedelta(days=d.weekday())
        return Period(start, start + timedelta(days=6))
    if step == "month":
        return _month_of(d.year, d.month)
    if step == "quarter":
        q = (d.month - 1) // 3
        return Period(date(d.year, 3 * q + 1, 1), _month_of(d.year, 3 * q + 3).end)
    return _year(d.year)


def periods(start, end, step):
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got '%s' and '%s'" % (start, end))
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    p = _containing(start, step)
    out = [p]
    while p.end < end:
        p = _containing(p.end + timedelta(days=1), step)
        out.append(p)
    return out
"""Chart of accounts: paths, types, patterns."""
import re

from .currency import CURRENCIES
from .dates import is_date
from .errors import ConflictError, NotFoundError, ValidationError
from .model import Account


class ChartError(ValidationError):
    pass


class _ChartConflict(ChartError, ConflictError):
    code = "conflict"


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEG_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOT_TYPES:
        return False
    return all(_SEG_RE.fullmatch(p) for p in parts)


def _need_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path '%s'" % (path,))


def parent_path(path):
    _need_path(path)
    head, sep, _ = path.rpartition(":")
    return head if sep else None


def account_type(path):
    _need_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern '%s'" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and not _SEG_RE.fullmatch(p):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return parts


def _match_segments(pat, segs):
    # pat: list of pattern parts, segs: list of path segments; full match
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for n in range(1, len(segs) + 1):
            if _match_segments(pat[1:], segs[n:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segments(pat[1:], segs[1:])
    return False


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pattern:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segments(parts, path.split(":"))


def _sort_key(path):
    return tuple(path.split(":"))


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_path(path)
        kind = ROOT_TYPES[path.split(":", 1)[0]]
        if type is not None and type != kind:
            if type not in TYPES:
                raise ChartError("unknown account type '%s'" % (type,))
            raise ChartError("account %s is of type %s, not %s" % (path, kind, type))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency '%s'" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, got '%s'" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text")
        if path in self._explicit:
            raise _ChartConflict("account %s already exists" % path)
        existing = self._accounts.get(path)
        if existing is not None:
            existing.currency = currency
            existing.opened = opened
            existing.note = note
            self._explicit.add(path)
            return existing
        parts = path.split(":")
        for i in range(1, len(parts)):
            p = ":".join(parts[:i])
            if p not in self._accounts:
                self._accounts[p] = Account(p, ROOT_TYPES[parts[0]])
        acct = Account(path, kind, currency, opened, None, note)
        self._accounts[path] = acct
        self._explicit.add(path)
        return acct

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account '%s'" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    __contains__ = exists

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=_sort_key)]

    def children(self, path):
        self.get(path)
        n = path.count(":") + 1
        return [a for a in self.accounts() if a.path.startswith(path + ":") and a.path.count(":") == n]

    def descendants(self, path):
        self.get(path)
        return [a for a in self.accounts() if a.path.startswith(path + ":")]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        a = self.get(path)
        if not is_date(on):
            raise ChartError("not a date: '%s'" % (on,))
        return (a.opened is None or a.opened <= on) and (a.closed is None or on <= a.closed)

