"""CSV and JSON export of transactions, and fixed-width text tables."""
import json

from .dates import format_date, is_date, parse_date
from .errors import ValidationError
from .model import Posting, Transaction
from .money import Money


class ExportError(ValidationError):
    pass


CSV_HEADER = ("id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note")


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


# -- CSV ------------------------------------------------------------------
def _csv_field(value):
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def _csv_record(cells):
    return ",".join(_csv_field(c) for c in cells) + "\n"


def to_csv(headers, rows):
    out = [_csv_record(headers)]
    for row in rows:
        out.append(_csv_record(row))
    return "".join(out)


def _tags(tx):
    return sorted(set(tx.tags))


def transactions_to_csv(txs):
    out = [_csv_record(CSV_HEADER)]
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            format_date(tx.date),
            tx.flag,
            tx.payee,
            tx.narration,
            ";".join(_tags(tx)),
        ]
        if not tx.postings:
            out.append(_csv_record(head + ["", "", "", ""]))
            continue
        for p in tx.postings:
            if p.amount is None:
                amount, cur = "", ""
            else:
                amount, cur = p.amount.amount_str(), p.amount.currency
            out.append(_csv_record(head + [p.account, amount, cur, p.note]))
    return "".join(out)


# -- JSON -----------------------------------------------------------------
def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    if not isinstance(money, Money):
        raise ExportError("not an amount of money: '%s'" % (money,))
    return {"amount": money.amount_str(), "currency": money.currency}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx),
        "postings": [
            {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
            for p in tx.postings
        ],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = ("id", "date", "flag", "payee", "narration", "tags", "postings")
_POSTING_KEYS = ("account", "amount", "note")


def _unknown_key(obj, known, where):
    for key in obj:
        if key not in known:
            raise ExportError("%s: unknown key '%s'" % (where, key))


def _read_money(obj, where):
    if obj is None:
        return None
    if not isinstance(obj, dict):
        raise ExportError("%s: amount must be null or an object with amount and currency" % where)
    if set(obj) != {"amount", "currency"}:
        raise ExportError("%s: amount must have exactly the keys amount and currency" % where)
    text, cur = obj["amount"], obj["currency"]
    if not isinstance(text, str) or not isinstance(cur, str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money.of(text, cur)
    except ValidationError as exc:
        raise ExportError("%s: invalid amount: %s" % (where, exc.message)) from None


def _read_posting(obj, where):
    if not isinstance(obj, dict):
        raise ExportError("%s: not an object" % where)
    _unknown_key(obj, _POSTING_KEYS, where)
    if "account" not in obj:
        raise ExportError("%s: missing 'account'" % where)
    account = obj["account"]
    if not isinstance(account, str):
        raise ExportError("%s: account must be text" % where)
    amount = _read_money(obj.get("amount"), where)
    note = obj.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    return Posting(account, amount, note)


def _read_transaction(obj, where):
    if not isinstance(obj, dict):
        raise ExportError("%s: not an object" % where)
    _unknown_key(obj, _TX_KEYS, where)
    for key in ("date", "payee", "postings"):
        if key not in obj:
            raise ExportError("%s: missing '%s'" % (where, key))
    raw_date = obj["date"]
    if not isinstance(raw_date, str):
        raise ExportError("%s: date must be text in the form YYYY-MM-DD" % where)
    try:
        day = parse_date(raw_date)
    except ValidationError:
        raise ExportError("%s: invalid date '%s'" % (where, raw_date)) from None
    except Exception:
        raise ExportError("%s: invalid date '%s'" % (where, raw_date)) from None
    tx_id = obj.get("id")
    if tx_id is not None and (not _is_int(tx_id) or tx_id < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1, got '%s'" % (where, tx_id))
    flag = obj.get("flag", "*")
    if not isinstance(flag, str) or flag not in ("*", "!"):
        raise ExportError("%s: flag must be '*' or '!', got '%s'" % (where, flag))
    payee = obj["payee"]
    if not isinstance(payee, str):
        raise ExportError("%s: payee must be text" % where)
    narration = obj.get("narration", "")
    if not isinstance(narration, str):
        raise ExportError("%s: narration must be text" % where)
    tags = obj.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    raw_postings = obj["postings"]
    if not isinstance(raw_postings, list):
        raise ExportError("%s: postings must be a list" % where)
    postings = [
        _read_posting(p, "%s posting %d" % (where, i)) for i, p in enumerate(raw_postings, 1)
    ]
    return Transaction(day, payee, narration, postings, tuple(sorted(set(tags))), flag, tx_id)


def transactions_from_json(text):
    if not isinstance(text, str):
        raise ExportError("not JSON: expected text")
    try:
        data = json.loads(text)
    except (ValueError, RecursionError) as exc:
        raise ExportError("not JSON: %s" % exc) from None
    if not isinstance(data, list):
        raise ExportError("expected a JSON array of transactions")
    return [_read_transaction(item, "transaction %d" % i) for i, item in enumerate(data, 1)]


# -- tables ---------------------------------------------------------------
def _cell(value):
    text = "" if value is None else str(value)
    if "\t" in text or "\r" in text or "\n" in text:
        text = text.replace("\t", " ").replace("\r", " ").replace("\n", " ")
    return text


def _alignment(align, count):
    if align is None:
        return ["l"] * count
    if not isinstance(align, (str, list, tuple)):
        raise ExportError("align must be None, a string or a list of 'l' and 'r'")
    letters = list(align)
    for letter in letters:
        if not isinstance(letter, str) or letter not in ("l", "r"):
            raise ExportError("invalid alignment '%s': use 'l' or 'r'" % (letter,))
    if len(letters) != count:
        raise ExportError("alignment has %d letters for %d columns" % (len(letters), count))
    return letters


def render_table(headers, rows, align=None):
    try:
        titles = [_cell(h) for h in headers]
    except TypeError:
        raise ExportError("headers must be an iterable of cells") from None
    if not titles:
        return ""
    count = len(titles)
    letters = _alignment(align, count)
    try:
        body = []
        for number, row in enumerate(rows, 1):
            try:
                cells = [_cell(c) for c in row]
            except TypeError:
                raise ExportError("row %d is not a sequence of cells" % number) from None
            if len(cells) != count:
                raise ExportError("row %d has %d cells for %d columns" % (number, len(cells), count))
            body.append(cells)
    except TypeError:
        raise ExportError("rows must be an iterable of rows") from None
    widths = [len(t) for t in titles]
    for cells in body:
        for i, c in enumerate(cells):
            if len(c) > widths[i]:
                widths[i] = len(c)

    def line(cells):
        parts = [
            c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, letters)
        ]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(titles), "  ".join("-" * w for w in widths) + "\n"]
    out.extend(line(cells) for cells in body)
    return "".join(out)

