class TransactionsFromJsonTest(unittest.TestCase):
    def test_empty_array(self):
        self.assertEqual(transactions_from_json("[]"), [])
        self.assertEqual(transactions_from_json("[]\n"), [])

    def test_round_trip(self):
        txs = [
            coffee(),
            T(2024, 1, 1, "No post", id=None),
            T(2024, 2, 2, "Blank", P("Assets:Cash", None, "n"), P("Assets:B", "900 JPY"), tags=("a",), id=3),
        ]
        self.assertEqual(transactions_from_json(transactions_to_json(txs)), txs)

    def test_result_types(self):
        (tx,) = transactions_from_json(transactions_to_json([coffee()]))
        self.assertIsInstance(tx, Transaction)
        self.assertEqual(tx.date, date(2024, 3, 1))
        self.assertIsInstance(tx.postings[0], Posting)
        self.assertEqual(tx.postings[0].amount, Money(450, "USD"))
        self.assertIsInstance(tx.tags, tuple)

    def test_defaults_when_keys_missing(self):
        (tx,) = transactions_from_json(dump({"date": "2024-03-01", "payee": "P", "postings": [{"account": "Assets:Cash"}]}))
        self.assertEqual(
            tx,
            Transaction(date(2024, 3, 1), "P", "", [Posting("Assets:Cash", None, "")], (), "*", None),
        )

    def test_empty_postings_allowed(self):
        (tx,) = transactions_from_json(dump({"date": "2024-03-01", "payee": "", "postings": []}))
        self.assertEqual(tx.postings, [])

    def test_id_null_or_missing_is_none_and_number_kept(self):
        rows = [({"id": None}, None), ({}, None), ({"id": 1}, 1), ({"id": 12345678901234567890}, 12345678901234567890)]
        for extra, expected in rows:
            with self.subTest(extra=extra):
                obj = tx_obj(**extra)
                if not extra:
                    del obj["id"]
                (tx,) = transactions_from_json(dump(obj))
                self.assertEqual(tx.id, expected)

    def test_tags_sorted_and_deduplicated(self):
        (tx,) = transactions_from_json(dump(tx_obj(tags=["b", "a", "b"])))
        self.assertEqual(tx.tags, ("a", "b"))

    def test_flags(self):
        for flag in ("*", "!"):
            with self.subTest(flag=flag):
                (tx,) = transactions_from_json(dump(tx_obj(flag=flag)))
                self.assertEqual(tx.flag, flag)

    def test_non_ascii_text(self):
        (tx,) = transactions_from_json(dump(tx_obj(payee="Café €")))
        self.assertEqual(tx.payee, "Café €")

    def test_money_with_currency_decimals(self):
        obj = tx_obj(postings=[
            {"account": "A", "amount": {"amount": "900", "currency": "JPY"}},
            {"account": "B", "amount": {"amount": "-1.234", "currency": "KWD"}},
        ])
        (tx,) = transactions_from_json(dump(obj))
        self.assertEqual([p.amount for p in tx.postings], [Money(900, "JPY"), Money(-1234, "KWD")])

    def assert_error(self, text, prefix, *contains):
        with self.assertRaises(ExportError) as ctx:
            transactions_from_json(text)
        self.assertTrue(ctx.exception.message.startswith(prefix), ctx.exception.message)
        for piece in contains:
            self.assertIn(piece, ctx.exception.message)
        self.assertEqual(ctx.exception.code, "validation")

    def test_whole_text_errors_have_no_position(self):
        rows = [
            ("not json", "not JSON"),
            ("", "not JSON"),
            ("[1,", "not JSON"),
            ("{}", "expected a JSON array"),
            ('{"a": 1}', "expected a JSON array"),
            ('"x"', "expected a JSON array"),
            ("null", "expected a JSON array"),
            ("5", "expected a JSON array"),
        ]
        for text, prefix in rows:
            with self.subTest(text=text):
                self.assert_error(text, prefix)
                with self.assertRaises(ExportError) as ctx:
                    transactions_from_json(text)
                self.assertNotIn("transaction", ctx.exception.message)

    def test_non_text_input_is_export_error(self):
        for bad in (None, 5, b"[]", []):
            with self.subTest(bad=bad):
                with self.assertRaises(ExportError):
                    transactions_from_json(bad)

    def test_deeply_nested_json_is_export_error(self):
        with self.assertRaises(ExportError):
            transactions_from_json("[" * 100000)

    def test_item_not_an_object(self):
        for item in (1, "x", None, [], True, 1.5):
            with self.subTest(item=item):
                self.assert_error(json.dumps([item]), "transaction 1")
                self.assert_error(json.dumps([tx_obj(), item]), "transaction 2")

    def test_position_counts_from_one(self):
        self.assert_error(dump(tx_obj(), tx_obj(), tx_obj(flag="x")), "transaction 3")

    def test_unknown_key_in_transaction(self):
        self.assert_error(dump(tx_obj(), tx_obj(colour="red")), "transaction 2", "colour")

    def test_unknown_key_in_posting(self):
        obj = tx_obj(postings=[{"account": "A"}, {"account": "B", "extra": 1}])
        self.assert_error(dump(tx_obj(), obj), "transaction 2 posting 2", "extra")

    def test_required_keys_missing(self):
        for key in ("date", "payee", "postings"):
            with self.subTest(key=key):
                obj = tx_obj()
                del obj[key]
                self.assert_error(dump(obj), "transaction 1", key)

    def test_bad_dates(self):
        bad = ["2024-3-1", "2024-02-30", "20240301", "2024/03/01", "", " 2024-03-01", "2024-13-01", "0000-01-01", "x"]
        for value in bad:
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(), tx_obj(date=value)), "transaction 2", "date", value)

    def test_date_not_text(self):
        for value in (None, 20240301, True, ["2024-03-01"]):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(date=value)), "transaction 1", "date")

    def test_bad_ids(self):
        for value in (0, -1, 1.5, 1.0, "3", True, False, [], {}):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(id=value)), "transaction 1", "id")

    def test_bad_flags(self):
        for value in ("", "x", "**", "!*", None, 1, True, ["*"]):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(flag=value)), "transaction 1", "flag")

    def test_text_fields_must_be_text(self):
        for key in ("payee", "narration"):
            for value in (None, 1, True, [], {}):
                with self.subTest(key=key, value=value):
                    self.assert_error(dump(tx_obj(**{key: value})), "transaction 1", key)

    def test_note_must_be_text(self):
        for value in (None, 1, True, []):
            with self.subTest(value=value):
                obj = tx_obj(postings=[{"account": "A", "note": value}])
                self.assert_error(dump(obj), "transaction 1 posting 1", "note")

    def test_bad_tags(self):
        for value in (None, "a", ["a", 1], ["a", None], 5, {"a": 1}, [["a"]], True):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(tags=value)), "transaction 1", "tags")

    def test_postings_not_a_list(self):
        for value in (None, {}, "x", 3):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(postings=value)), "transaction 1", "postings")

    def test_posting_not_an_object(self):
        for item in (None, 1, "x", []):
            with self.subTest(item=item):
                obj = tx_obj(postings=[{"account": "A"}, item])
                self.assert_error(dump(obj), "transaction 1 posting 2")

    def test_posting_account_missing_or_not_text(self):
        for obj in ({}, {"account": None}, {"account": 3}, {"account": ["A"]}):
            with self.subTest(obj=obj):
                self.assert_error(dump(tx_obj(postings=[{"account": "A"}, obj])), "transaction 1 posting 2", "account")

    def test_bad_amounts(self):
        rows = [
            {"amount": "4.505", "currency": "USD"},
            {"amount": "4.50", "currency": "XXX"},
            {"amount": "4.50", "currency": "usd"},
            {"amount": "4.50"},
            {"currency": "USD"},
            {"amount": "4.50", "currency": "USD", "extra": 1},
            {},
            {"amount": 4.5, "currency": "USD"},
            {"amount": "4.50", "currency": 1},
            {"amount": None, "currency": "USD"},
            {"amount": "abc", "currency": "USD"},
            {"amount": "", "currency": "USD"},
            {"amount": "1.5", "currency": "JPY"},
            {"amount": "1.2345", "currency": "KWD"},
            "4.50 USD",
