        ]
        for amount in rows:
            with self.subTest(amount=amount):
                obj = tx_obj(postings=[{"account": "A"}, {"account": "B", "amount": amount}])
                self.assert_error(dump(tx_obj(), obj), "transaction 2 posting 2", "amount")

    def test_invalid_money_message_carries_reason(self):
        obj = tx_obj(postings=[{"account": "A", "amount": {"amount": "4.505", "currency": "USD"}}])
        self.assert_error(dump(obj), "transaction 1 posting 1", "4.505")
        obj = tx_obj(postings=[{"account": "A", "amount": {"amount": "1.00", "currency": "XXX"}}])
        self.assert_error(dump(obj), "transaction 1 posting 1", "XXX")

    def test_first_posting_position(self):
