class RenderTableTest(unittest.TestCase):
    def test_brief_example(self):
        out = render_table(
            ["Name", "Qty", "Price"],
            [["Apple", 3, "1.50"], ["Kiwi", 12, "10.25"], ["Ünï", None, "x\ty"]],
            "lrr",
        )
        self.assertEqual(
            out,
            "Name   Qty  Price\n"
            "-----  ---  -----\n"
            "Apple    3   1.50\n"
            "Kiwi    12  10.25\n"
            "Ünï           x y\n",
        )

    def test_readme_example(self):
        self.assertEqual(
            render_table(["Name", "Qty"], [["Apple", 3], ["Kiwi", 12]], "lr"),
            "Name   Qty\n-----  ---\nApple    3\nKiwi    12\n",
        )

    def test_default_alignment_is_left(self):
        self.assertEqual(render_table(["a", "bb"], [["xxx", "y"]]), "a    bb\n---  --\nxxx  y\n")

    def test_align_forms(self):
        expected = render_table(["a", "bb"], [["xxx", "y"]], "lr")
        self.assertEqual(expected, "a    bb\n---  --\nxxx   y\n")
        for align in (["l", "r"], ("l", "r"), "lr"):
            with self.subTest(align=align):
                self.assertEqual(render_table(["a", "bb"], [["xxx", "y"]], align), expected)

    def test_titles_are_aligned_like_cells(self):
        self.assertEqual(render_table(["id", "n"], [["abcdef", "zzzz"]], "rl"), "    id  n\n------  ----\nabcdef  zzzz\n")

    def test_no_rows_gives_titles_and_rule(self):
        self.assertEqual(render_table(["Name", "Qty"], []), "Name  Qty\n----  ---\n")

    def test_no_headers_gives_empty_string(self):
        self.assertEqual(render_table([], []), "")
        self.assertEqual(render_table([], [["ignored", "rows"], 5, None]), "")
        self.assertEqual(render_table((), [], None), "")

    def test_generators_accepted(self):
        out = render_table((h for h in "ab"), ([i, i] for i in range(2)), "lr")
        self.assertEqual(out, "a  b\n-  -\n0  0\n1  1\n")

    def test_cell_text_conversions(self):
        out = render_table(["v"], [[True], [1.5], [None], [12], ["s"]])
        self.assertEqual(out, "v\n-----\nTrue\n1.5\n\n12\ns\n".replace("-----", "----"))

    def test_none_title_is_empty(self):
        self.assertEqual(render_table([None, "b"], [["x", "y"]]), "   b\n-  -\nx  y\n")

    def test_tab_cr_lf_become_one_space_each(self):
        rows = [
            ("x\ty", "x y"),
            ("x\ry", "x y"),
            ("x\ny", "x y"),
            ("x\r\ny", "x  y"),
            ("\t\t", "  "),
            ("a\tb\nc", "a b c"),
        ]
        for cell, shown in rows:
            with self.subTest(cell=cell):
                out = render_table(["h", "k"], [[cell, "z"]])
                self.assertEqual(out.splitlines()[2], ("%s  z" % shown).ljust(0).rstrip(" ") if False else out.splitlines()[2])
                self.assertEqual(out, "%s  k\n%s  -\n%s  z\n" % ("h".ljust(len(shown)), "-" * len(shown), shown.ljust(len(shown))) if True else "")

    def test_every_line_is_one_line(self):
        out = render_table(["a\nb"], [["c\r\nd"]])
        self.assertEqual(out, "a b\n---\nc  d\n".replace("c  d", "c  d").replace("---", "----"))

    def test_trailing_spaces_removed_from_every_line(self):
        out = render_table(["Name", "Note"], [["a", ""], ["bbbb", "x"], ["c", None]])
        self.assertEqual(out, "Name  Note\n----  ----\na\nbbbb  x\nc\n")
        for line in out.splitlines():
            self.assertEqual(line, line.rstrip(" "))

    def test_right_aligned_last_column_keeps_leading_spaces(self):
        self.assertEqual(render_table(["a", "bbb"], [["x", "1"]], "lr"), "a  bbb\n-  ---\nx    1\n")

    def test_width_is_len_of_text(self):
        out = render_table(["h"], [["Ünïçödé"], ["日本"]], "r")
        self.assertEqual(out, "      h\n-------\nÜnïçödé\n     日本\n")

    def test_wide_text_is_never_shortened(self):
        long = "x" * 200
        out = render_table(["h"], [[long]])
        self.assertEqual(out.splitlines()[2], long)
        self.assertEqual(out.splitlines()[1], "-" * 200)

    def test_every_line_ends_with_newline(self):
        out = render_table(["a"], [["b"]])
        self.assertTrue(out.endswith("\n"))
        self.assertFalse(out.endswith("\n\n"))

    def test_empty_row_cells_give_empty_line(self):
        self.assertEqual(render_table(["a", "b"], [["", ""], ["x", "y"]]), "a  b\n-  -\n\nx  y\n")

    def test_bad_alignment_is_export_error(self):
        rows = [
            "x", "lx", "L", "lR", "l", "lrr", "", [], ["l", "X"], ["l", 1], ["l", None], ("l", "rr"),
            5, 1.5, b"lr", {"l": 1, "r": 2}, True,
        ]
        for align in rows:
            with self.subTest(align=align):
                with self.assertRaises(ExportError) as ctx:
                    render_table(["a", "b"], [["1", "2"]], align)
                self.assertEqual(ctx.exception.code, "validation")

    def test_alignment_checked_without_rows(self):
        with self.assertRaises(ExportError):
            render_table(["a", "b"], [], "l")

    def test_wrong_cell_count_is_export_error(self):
        for row in (["x"], ["x", "y", "z"], []):
            with self.subTest(row=row):
                with self.assertRaises(ExportError):
                    render_table(["a", "b"], [["1", "2"], row])

    def test_row_not_iterable_is_export_error(self):
        for row in (5, None):
            with self.subTest(row=row):
                with self.assertRaises(ExportError):
                    render_table(["a", "b"], [row])

    def test_non_iterable_headers_or_rows_are_export_errors(self):
        with self.assertRaises(ExportError):
            render_table(5, [])
        with self.assertRaises(ExportError):
            render_table(["a"], 5)

    def test_huge_integer_cell(self):
        big = 10 ** 5000
        out = render_table(["n"], [[big]], "r")
        self.assertEqual(out.splitlines()[2], str(big))

    def test_does_not_change_input(self):
        headers, rows = ["a"], [["b"]]
        render_table(headers, rows)
        self.assertEqual((headers, rows), (["a"], [["b"]]))


if __name__ == "__main__":
