from tests.helpers import P, T

HEADER = "id,date,flag,payee,narration,tags,account,amount,currency,note\n"


def coffee():
    return T(
        2024, 3, 1, "Caf\u00e9, B\u00e4cker",
        P("Expenses:Food", "4.50 USD", "a, b"), P("Assets:Cash", "-4.50 USD"),
        narration='say "hi"', tags=("a", "lunch"), flag="!", id=7,
