import json
import unittest
from datetime import date

from tallybook.errors import TallybookError, ValidationError
from tallybook.export import (
    ExportError,
    money_to_dict,
    render_table,
    to_csv,
    to_json,
    transaction_to_dict,
    transactions_from_json,
    transactions_to_csv,
    transactions_to_json,
)
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tests.helpers import P, T

HEADER = "id,date,flag,payee,narration,tags,account,amount,currency,note\n"


def coffee():
    return T(
        2024, 3, 1, "Café, Bäcker",
        P("Expenses:Food", "4.50 USD", "a, b"), P("Assets:Cash", "-4.50 USD"),
        narration='say "hi"', tags=("a", "lunch"), flag="!", id=7,
    )


def tx_obj(**over):
    obj = {
        "id": 3, "date": "2024-03-01", "flag": "!", "payee": "Acme", "narration": "n",
        "tags": ["a", "b"],
        "postings": [
            {"account": "Assets:Cash", "amount": {"amount": "4.50", "currency": "USD"}, "note": "x"},
            {"account": "Expenses:Food", "amount": None, "note": ""},
        ],
    }
    obj.update(over)
    return obj


def dump(*items):
    return json.dumps(list(items))


class ErrorClassTest(unittest.TestCase):
    def test_export_error_is_validation_error(self):
        self.assertTrue(issubclass(ExportError, ValidationError))
        self.assertTrue(issubclass(ExportError, TallybookError))
        self.assertEqual(ExportError("x").code, "validation")
        self.assertEqual(str(ExportError("boom")), "boom")


class TransactionsToCsvTest(unittest.TestCase):
    def test_no_transactions_gives_header_only(self):
        self.assertEqual(transactions_to_csv([]), HEADER)

    def test_coffee_example_exact(self):
        expected = (
            HEADER
            + '7,2024-03-01,!,"Café, Bäcker","say ""hi""",a;lunch,Expenses:Food,4.50,USD,"a, b"\n'
            + '7,2024-03-01,!,"Café, Bäcker","say ""hi""",a;lunch,Assets:Cash,-4.50,USD,\n'
        )
        self.assertEqual(transactions_to_csv([coffee()]), expected)

    def test_id_none_is_empty(self):
        tx = T(2024, 3, 1, "P", P("Assets:Cash", "1.00 USD"))
        self.assertEqual(transactions_to_csv([tx]), HEADER + ",2024-03-01,*,P,,,Assets:Cash,1.00,USD,\n")

    def test_amount_formats_per_currency(self):
        rows = [
            ("900 JPY", "900", "JPY"),
            ("-900 JPY", "-900", "JPY"),
            ("4.50 USD", "4.50", "USD"),
            ("-4.50 USD", "-4.50", "USD"),
            ("1.234 KWD", "1.234", "KWD"),
            ("1234567.00 EUR", "1234567.00", "EUR"),
            ("0.05 USD", "0.05", "USD"),
        ]
        for text, amount, cur in rows:
            with self.subTest(text=text):
                out = transactions_to_csv([T(2024, 1, 1, "P", P("Assets:Cash", text), id=1)])
                self.assertEqual(out, HEADER + "1,2024-01-01,*,P,,,Assets:Cash,%s,%s,\n" % (amount, cur))

    def test_posting_without_amount_gives_empty_amount_and_currency(self):
        tx = T(2024, 1, 1, "P", P("Assets:Cash", None, "memo"), id=2)
        self.assertEqual(transactions_to_csv([tx]), HEADER + "2,2024-01-01,*,P,,,Assets:Cash,,,memo\n")

    def test_transaction_without_postings_gives_one_record(self):
        tx = T(2024, 1, 1, "P", narration="n", tags=("b", "a"), flag="!", id=5)
        self.assertEqual(transactions_to_csv([tx]), HEADER + "5,2024-01-01,!,P,n,a;b,,,,\n")

    def test_first_six_fields_repeat_on_every_posting(self):
        tx = T(2024, 1, 1, "P", P("Assets:Cash", "3.00 USD"), P("Expenses:Food", "-1.00 USD"),
               P("Expenses:Rent", "-2.00 USD"), narration="n", tags=("t",), id=9)
        lines = transactions_to_csv([tx]).splitlines()
        self.assertEqual(len(lines), 4)
        for line in lines[1:]:
            self.assertTrue(line.startswith("9,2024-01-01,*,P,n,t,"))

    def test_tags_sorted_deduplicated_joined_with_semicolon(self):
        rows = [
            (("b", "a"), "a;b"),
            (["z", "Z", "a"], "Z;a;z"),
            (("a", "a", "b", "a"), "a;b"),
            ((), ""),
            (("only",), "only"),
        ]
        for tags, expected in rows:
            with self.subTest(tags=tags):
                tx = T(2024, 1, 1, "P", P("Assets:Cash", "1.00 USD"), tags=tags, id=1)
                self.assertEqual(
                    transactions_to_csv([tx]), HEADER + "1,2024-01-01,*,P,,%s,Assets:Cash,1.00,USD,\n" % expected
                )

    def test_quoting_only_for_comma_quote_cr_lf(self):
        rows = [
            ("a,b", '"a,b"'),
            ('a"b', '"a""b"'),
            ("a\rb", '"a\rb"'),
            ("a\nb", '"a\nb"'),
            ("a\r\nb", '"a\r\nb"'),
            ('"', '""""'),
            ("a b", "a b"),
            ("a\tb", "a\tb"),
            (" a ", " a "),
            ("café € 日本", "café € 日本"),
            ("", ""),
            ("a;b", "a;b"),
            ("a'b", "a'b"),
        ]
        for payee, field in rows:
            with self.subTest(payee=payee):
                tx = Transaction(date(2024, 1, 1), payee, "", [], (), "*", 1)
                self.assertEqual(transactions_to_csv([tx]), HEADER + "1,2024-01-01,*,%s,,,,,,\n" % field)

    def test_note_and_account_are_quoted_too(self):
        tx = T(2024, 1, 1, "P", P("Assets:Cash", "1.00 USD", 'he said "x", ok'), id=1)
        self.assertEqual(
            transactions_to_csv([tx]), HEADER + '1,2024-01-01,*,P,,,Assets:Cash,1.00,USD,"he said ""x"", ok"\n'
        )

    def test_records_end_with_single_lf_never_crlf(self):
        out = transactions_to_csv([coffee()])
        self.assertTrue(out.endswith("\n"))
        self.assertFalse(out.endswith("\n\n"))
        self.assertNotIn("\r\n", out)

    def test_order_is_given_order_not_sorted(self):
        a = T(2024, 5, 1, "A", P("Assets:Cash", "1.00 USD"), id=9)
        b = T(2024, 1, 1, "B", P("Assets:Cash", "1.00 USD"), id=2)
        lines = transactions_to_csv([a, b]).splitlines()
        self.assertTrue(lines[1].startswith("9,"))
        self.assertTrue(lines[2].startswith("2,"))

    def test_accepts_any_iterable(self):
        tx = T(2024, 1, 1, "P", P("Assets:Cash", "1.00 USD"), id=1)
        for name, source in (("tuple", (tx,)), ("generator", (t for t in [tx]))):
            with self.subTest(name=name):
                self.assertEqual(len(transactions_to_csv(source).splitlines()), 2)

    def test_unbalanced_transaction_exported_as_is(self):
        tx = T(2024, 1, 1, "P", P("Assets:Cash", "5.00 USD"), P("Expenses:Food", "1.00 USD"), id=1)
        self.assertEqual(len(transactions_to_csv([tx]).splitlines()), 3)

    def test_does_not_change_input(self):
        tx = coffee()
        before = (list(tx.postings), tx.tags)
