        self.assertEqual([p["account"] for p in transaction_to_dict(tx)["postings"]], ["Assets:B", "Assets:A"])


class ToJsonTest(unittest.TestCase):
    def test_format_indent_sorted_keys_unescaped_and_newline(self):
        self.assertEqual(to_json({"b": 1, "a": [1, 2]}), '{\n  "a": [\n    1,\n    2\n  ],\n  "b": 1\n}\n')

    def test_non_ascii_written_as_is(self):
        self.assertEqual(to_json("caf\u00e9 \u20ac"), '"caf\u00e9 \u20ac"\n')

    def test_empty_list_and_dict(self):
        self.assertEqual(to_json([]), "[]\n")
        self.assertEqual(to_json({}), "{}\n")

    def test_scalars(self):
        rows = [(None, "null\n"), (True, "true\n"), (5, "5\n"), ("x", '"x"\n')]
        for value, expected in rows:
            with self.subTest(value=value):
                self.assertEqual(to_json(value), expected)

    def test_matches_json_dumps_recipe(self):
        value = {"z": [{"b": None, "a": "\u00fc"}], "a": 1}
        self.assertEqual(to_json(value), json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n")


class TransactionsToJsonTest(unittest.TestCase):
    def test_no_transactions(self):
        self.assertEqual(transactions_to_json([]), "[]\n")

    def test_coffee_exact_text(self):
        expected = (
            '[\n'
            '  {\n'
            '    "date": "2024-03-01",\n'
            '    "flag": "!",\n'
            '    "id": 7,\n'
            '    "narration": "say \\"hi\\"",\n'
            '    "payee": "Caf\u00e9, B\u00e4cker",\n'
            '    "postings": [\n'
            '      {\n'
            '        "account": "Expenses:Food",\n'
            '        "amount": {\n'
            '          "amount": "4.50",\n'
            '          "currency": "USD"\n'
            '        },\n'
            '        "note": "a, b"\n'
            '      },\n'
            '      {\n'
            '        "account": "Assets:Cash",\n'
            '        "amount": {\n'
            '          "amount": "-4.50",\n'
            '          "currency": "USD"\n'
            '        },\n'
            '        "note": ""\n'
            '      }\n'
            '    ],\n'
            '    "tags": [\n'
            '      "a",\n'
            '      "lunch"\n'
            '    ]\n'
            '  }\n'
            ']\n'
        )
        self.assertEqual(transactions_to_json([coffee()]), expected)

    def test_values_and_order(self):
        a = T(2024, 5, 1, "A", P("Assets:Cash", None), id=9)
        b = T(2024, 1, 1, "B", id=None, tags=("y", "x", "y"))
        data = json.loads(transactions_to_json(iter([a, b])))
        self.assertEqual([d["payee"] for d in data], ["A", "B"])
        self.assertEqual(data[0]["id"], 9)
        self.assertIsNone(data[1]["id"])
        self.assertIsNone(data[0]["postings"][0]["amount"])
        self.assertEqual(data[1]["tags"], ["x", "y"])
        self.assertEqual(data[1]["postings"], [])

    def test_ends_with_one_newline(self):
        out = transactions_to_json([coffee()])
        self.assertTrue(out.endswith("]\n"))
        self.assertFalse(out.endswith("\n\n"))


class TransactionsFromJsonTest(unittest.TestCase):
    def test_empty_array(self):
        self.assertEqual(transactions_from_json("[]"), [])
        self.assertEqual(transactions_from_json("[]\n"), [])

    def test_round_trip(self):
        txs = [
            coffee(),
            T(2024, 1, 1, "No post", id=None),
            T(2024, 2, 2, "Blank", P("Assets:Cash", None, "n"), P("Assets:B", "900 JPY"), tags=("a",), id=3),
        ]
        self.assertEqual(transactions_from_json(transactions_to_json(txs)), txs)

    def test_result_types(self):
        (tx,) = transactions_from_json(transactions_to_json([coffee()]))
        self.assertIsInstance(tx, Transaction)
        self.assertEqual(tx.date, date(2024, 3, 1))
        self.assertIsInstance(tx.postings[0], Posting)
        self.assertEqual(tx.postings[0].amount, Money(450, "USD"))
        self.assertIsInstance(tx.tags, tuple)

    def test_defaults_when_keys_missing(self):
        (tx,) = transactions_from_json(dump({"date": "2024-03-01", "payee": "P", "postings": [{"account": "Assets:Cash"}]}))
        self.assertEqual(
            tx,
            Transaction(date(2024, 3, 1), "P", "", [Posting("Assets:Cash", None, "")], (), "*", None),
        )

    def test_empty_postings_allowed(self):
        (tx,) = transactions_from_json(dump({"date": "2024-03-01", "payee": "", "postings": []}))
        self.assertEqual(tx.postings, [])

    def test_id_null_or_missing_is_none_and_number_kept(self):
        rows = [({"id": None}, None), ({}, None), ({"id": 1}, 1), ({"id": 12345678901234567890}, 12345678901234567890)]
        for extra, expected in rows:
            with self.subTest(extra=extra):
                obj = tx_obj(**extra)
                if not extra:
                    del obj["id"]
                (tx,) = transactions_from_json(dump(obj))
                self.assertEqual(tx.id, expected)

    def test_tags_sorted_and_deduplicated(self):
        (tx,) = transactions_from_json(dump(tx_obj(tags=["b", "a", "b"])))
        self.assertEqual(tx.tags, ("a", "b"))

    def test_flags(self):
        for flag in ("*", "!"):
            with self.subTest(flag=flag):
                (tx,) = transactions_from_json(dump(tx_obj(flag=flag)))
                self.assertEqual(tx.flag, flag)

    def test_non_ascii_text(self):
        (tx,) = transactions_from_json(dump(tx_obj(payee="Caf\u00e9 \u20ac")))
        self.assertEqual(tx.payee, "Caf\u00e9 \u20ac")

    def test_money_with_currency_decimals(self):
        obj = tx_obj(postings=[
            {"account": "A", "amount": {"amount": "900", "currency": "JPY"}},
            {"account": "B", "amount": {"amount": "-1.234", "currency": "KWD"}},
        ])
        (tx,) = transactions_from_json(dump(obj))
        self.assertEqual([p.amount for p in tx.postings], [Money(900, "JPY"), Money(-1234, "KWD")])

    def assert_error(self, text, prefix, *contains):
        with self.assertRaises(ExportError) as ctx:
            transactions_from_json(text)
        self.assertTrue(ctx.exception.message.startswith(prefix), ctx.exception.message)
        for piece in contains:
            self.assertIn(piece, ctx.exception.message)
        self.assertEqual(ctx.exception.code, "validation")

    def test_whole_text_errors_have_no_position(self):
        rows = [
            ("not json", "not JSON"),
            ("", "not JSON"),
            ("[1,", "not JSON"),
            ("{}", "expected a JSON array"),
            ('{"a": 1}', "expected a JSON array"),
            ('"x"', "expected a JSON array"),
            ("null", "expected a JSON array"),
            ("5", "expected a JSON array"),
        ]
        for text, prefix in rows:
            with self.subTest(text=text):
                self.assert_error(text, prefix)
                with self.assertRaises(ExportError) as ctx:
                    transactions_from_json(text)
                self.assertNotIn("transaction", ctx.exception.message)

    def test_non_text_input_is_export_error(self):
        for bad in (None, 5, b"[]", []):
            with self.subTest(bad=bad):
                with self.assertRaises(ExportError):
                    transactions_from_json(bad)

    def test_deeply_nested_json_is_export_error(self):
        with self.assertRaises(ExportError):
            transactions_from_json("[" * 100000)

    def test_item_not_an_object(self):
        for item in (1, "x", None, [], True, 1.5):
            with self.subTest(item=item):
                self.assert_error(json.dumps([item]), "transaction 1")
                self.assert_error(json.dumps([tx_obj(), item]), "transaction 2")

    def test_position_counts_from_one(self):
        self.assert_error(dump(tx_obj(), tx_obj(), tx_obj(flag="x")), "transaction 3")

    def test_unknown_key_in_transaction(self):
        self.assert_error(dump(tx_obj(), tx_obj(colour="red")), "transaction 2", "colour")

    def test_unknown_key_in_posting(self):
        obj = tx_obj(postings=[{"account": "A"}, {"account": "B", "extra": 1}])
        self.assert_error(dump(tx_obj(), obj), "transaction 2 posting 2", "extra")

    def test_required_keys_missing(self):
        for key in ("date", "payee", "postings"):
            with self.subTest(key=key):
                obj = tx_obj()
                del obj[key]
                self.assert_error(dump(obj), "transaction 1", key)

    def test_bad_dates(self):
        bad = ["2024-3-1", "2024-02-30", "20240301", "2024/03/01", "", " 2024-03-01", "2024-13-01", "0000-01-01", "x"]
        for value in bad:
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(), tx_obj(date=value)), "transaction 2", "date", value)

    def test_date_not_text(self):
        for value in (None, 20240301, True, ["2024-03-01"]):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(date=value)), "transaction 1", "date")

    def test_bad_ids(self):
        for value in (0, -1, 1.5, 1.0, "3", True, False, [], {}):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(id=value)), "transaction 1", "id")

    def test_bad_flags(self):
        for value in ("", "x", "**", "!*", None, 1, True, ["*"]):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(flag=value)), "transaction 1", "flag")

    def test_text_fields_must_be_text(self):
        for key in ("payee", "narration"):
            for value in (None, 1, True, [], {}):
                with self.subTest(key=key, value=value):
                    self.assert_error(dump(tx_obj(**{key: value})), "transaction 1", key)

    def test_note_must_be_text(self):
        for value in (None, 1, True, []):
            with self.subTest(value=value):
                obj = tx_obj(postings=[{"account": "A", "note": value}])
                self.assert_error(dump(obj), "transaction 1 posting 1", "note")

    def test_bad_tags(self):
        for value in (None, "a", ["a", 1], ["a", None], 5, {"a": 1}, [["a"]], True):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(tags=value)), "transaction 1", "tags")

    def test_postings_not_a_list(self):
        for value in (None, {}, "x", 3):
            with self.subTest(value=value):
                self.assert_error(dump(tx_obj(postings=value)), "transaction 1", "postings")

    def test_posting_not_an_object(self):
        for item in (None, 1, "x", []):
            with self.subTest(item=item):
                obj = tx_obj(postings=[{"account": "A"}, item])
                self.assert_error(dump(obj), "transaction 1 posting 2")

    def test_posting_account_missing_or_not_text(self):
        for obj in ({}, {"account": None}, {"account": 3}, {"account": ["A"]}):
            with self.subTest(obj=obj):
                self.assert_error(dump(tx_obj(postings=[{"account": "A"}, obj])), "transaction 1 posting 2", "account")

    def test_bad_amounts(self):
        rows = [
            {"amount": "4.505", "currency": "USD"},
            {"amount": "4.50", "currency": "XXX"},
            {"amount": "4.50", "currency": "usd"},
            {"amount": "4.50"},
            {"currency": "USD"},
            {"amount": "4.50", "currency": "USD", "extra": 1},
            {},
            {"amount": 4.5, "currency": "USD"},
            {"amount": "4.50", "currency": 1},
            {"amount": None, "currency": "USD"},
            {"amount": "abc", "currency": "USD"},
            {"amount": "", "currency": "USD"},
            {"amount": "1.5", "currency": "JPY"},
            {"amount": "1.2345", "currency": "KWD"},
            "4.50 USD",
            4.5,
            [],
            True,
        ]
        for amount in rows:
            with self.subTest(amount=amount):
                obj = tx_obj(postings=[{"account": "A"}, {"account": "B", "amount": amount}])
                self.assert_error(dump(tx_obj(), obj), "transaction 2 posting 2", "amount")

    def test_invalid_money_message_carries_reason(self):
        obj = tx_obj(postings=[{"account": "A", "amount": {"amount": "4.505", "currency": "USD"}}])
        self.assert_error(dump(obj), "transaction 1 posting 1", "4.505")
        obj = tx_obj(postings=[{"account": "A", "amount": {"amount": "1.00", "currency": "XXX"}}])
        self.assert_error(dump(obj), "transaction 1 posting 1", "XXX")

    def test_first_posting_position(self):
        obj = tx_obj(postings=[{"account": 1}])
        self.assert_error(dump(obj), "transaction 1 posting 1")


class RenderTableTest(unittest.TestCase):
    def test_brief_example(self):
        out = render_table(
            ["Name", "Qty", "Price"],
            [["Apple", 3, "1.50"], ["Kiwi", 12, "10.25"], ["\u00dcn\u00ef", None, "x\ty"]],
            "lrr",
        )
        self.assertEqual(
            out,
            "Name   Qty  Price\n"
            "-----  ---  -----\n"
            "Apple    3   1.50\n"
            "Kiwi    12  10.25\n"
            "\u00dcn\u00ef           x y\n",
        )

    def test_readme_example(self):
        self.assertEqual(
            render_table(["Name", "Qty"], [["Apple", 3], ["Kiwi", 12]], "lr"),
            "Name   Qty\n-----  ---\nApple    3\nKiwi    12\n",
        )

    def test_default_alignment_is_left(self):
        self.assertEqual(render_table(["a", "bb"], [["xxx", "y"]]), "a    bb\n---  --\nxxx  y\n")

    def test_align_forms(self):
        expected = render_table(["a", "bb"], [["xxx", "y"]], "lr")
        self.assertEqual(expected, "a    bb\n---  --\nxxx   y\n")
        for align in (["l", "r"], ("l", "r"), "lr"):
            with self.subTest(align=align):
                self.assertEqual(render_table(["a", "bb"], [["xxx", "y"]], align), expected)

    def test_titles_are_aligned_like_cells(self):
        self.assertEqual(render_table(["id", "n"], [["abcdef", "zzzz"]], "rl"), "    id  n\n------  ----\nabcdef  zzzz\n")

    def test_no_rows_gives_titles_and_rule(self):
        self.assertEqual(render_table(["Name", "Qty"], []), "Name  Qty\n----  ---\n")

    def test_no_headers_gives_empty_string(self):
        self.assertEqual(render_table([], []), "")
        self.assertEqual(render_table([], [["ignored", "rows"], 5, None]), "")
        self.assertEqual(render_table((), [], None), "")

    def test_generators_accepted(self):
        out = render_table((h for h in "ab"), ([i, i] for i in range(2)), "lr")
        self.assertEqual(out, "a  b\n-  -\n0  0\n1  1\n")

    def test_cell_text_conversions(self):
        out = render_table(["v"], [[True], [1.5], [None], [12], ["s"]])
        self.assertEqual(out, "v\n-----\nTrue\n1.5\n\n12\ns\n".replace("-----", "----"))

    def test_none_title_is_empty(self):
        self.assertEqual(render_table([None, "b"], [["x", "y"]]), "   b\n-  -\nx  y\n")

    def test_tab_cr_lf_become_one_space_each(self):
        rows = [
            ("x\ty", "x y"),
            ("x\ry", "x y"),
            ("x\ny", "x y"),
            ("x\r\ny", "x  y"),
            ("\t\t", "  "),
            ("a\tb\nc", "a b c"),
        ]
        for cell, shown in rows:
            with self.subTest(cell=cell):
                out = render_table(["h", "k"], [[cell, "z"]])
                self.assertEqual(out.splitlines()[2], ("%s  z" % shown).ljust(0).rstrip(" ") if False else out.splitlines()[2])
                self.assertEqual(out, "%s  k\n%s  -\n%s  z\n" % ("h".ljust(len(shown)), "-" * len(shown), shown.ljust(len(shown))) if True else "")

    def test_every_line_is_one_line(self):
        out = render_table(["a\nb"], [["c\r\nd"]])
        self.assertEqual(out, "a b\n---\nc  d\n".replace("c  d", "c  d").replace("---", "----"))

    def test_trailing_spaces_removed_from_every_line(self):
        out = render_table(["Name", "Note"], [["a", ""], ["bbbb", "x"], ["c", None]])
        self.assertEqual(out, "Name  Note\n----  ----\na\nbbbb  x\nc\n")
        for line in out.splitlines():
            self.assertEqual(line, line.rstrip(" "))

    def test_right_aligned_last_column_keeps_leading_spaces(self):
        self.assertEqual(render_table(["a", "bbb"], [["x", "1"]], "lr"), "a  bbb\n-  ---\nx    1\n")

    def test_width_is_len_of_text(self):
        out = render_table(["h"], [["\u00dcn\u00ef\u00e7\u00f6d\u00e9"], ["\u65e5\u672c"]], "r")
        self.assertEqual(out, "      h\n-------\n\u00dcn\u00ef\u00e7\u00f6d\u00e9\n     \u65e5\u672c\n")

    def test_wide_text_is_never_shortened(self):
        long = "x" * 200
        out = render_table(["h"], [[long]])
        self.assertEqual(out.splitlines()[2], long)
        self.assertEqual(out.splitlines()[1], "-" * 200)

    def test_every_line_ends_with_newline(self):
        out = render_table(["a"], [["b"]])
        self.assertTrue(out.endswith("\n"))
        self.assertFalse(out.endswith("\n\n"))

    def test_empty_row_cells_give_empty_line(self):
        self.assertEqual(render_table(["a", "b"], [["", ""], ["x", "y"]]), "a  b\n-  -\n\nx  y\n")

    def test_bad_alignment_is_export_error(self):
        rows = [
            "x", "lx", "L", "lR", "l", "lrr", "", [], ["l", "X"], ["l", 1], ["l", None], ("l", "rr"),
            5, 1.5, b"lr", {"l": 1, "r": 2}, True,
        ]
        for align in rows:
            with self.subTest(align=align):
                with self.assertRaises(ExportError) as ctx:
                    render_table(["a", "b"], [["1", "2"]], align)
                self.assertEqual(ctx.exception.code, "validation")

    def test_alignment_checked_without_rows(self):
        with self.assertRaises(ExportError):
            render_table(["a", "b"], [], "l")

    def test_wrong_cell_count_is_export_error(self):
        for row in (["x"], ["x", "y", "z"], []):
            with self.subTest(row=row):
                with self.assertRaises(ExportError):
                    render_table(["a", "b"], [["1", "2"], row])

    def test_row_not_iterable_is_export_error(self):
        for row in (5, None):
            with self.subTest(row=row):
                with self.assertRaises(ExportError):
                    render_table(["a", "b"], [row])

    def test_non_iterable_headers_or_rows_are_export_errors(self):
        with self.assertRaises(ExportError):
            render_table(5, [])
        with self.assertRaises(ExportError):
            render_table(["a"], 5)

    def test_huge_integer_cell(self):
        big = 10 ** 5000
        out = render_table(["n"], [[big]], "r")
        self.assertEqual(out.splitlines()[2], str(big))

    def test_does_not_change_input(self):
        headers, rows = ["a"], [["b"]]
        render_table(headers, rows)
        self.assertEqual((headers, rows), (["a"], [["b"]]))


if __name__ == "__main__":
    unittest.main()
